formal.sparql:
# CQ-1: Which active sessions were established from an authentication
# journey execution below AAL2, and for which principals?
PREFIX core:    <https://w3id.org/examplebank/platform/core#>
PREFIX authn:   <https://w3id.org/examplebank/platform/authn#>
PREFIX session: <https://w3id.org/examplebank/platform/session#>

SELECT ?session ?principal ?aal WHERE {
    ?session a session:Session ;
             session:hasState session:state-active ;
             session:boundToPrincipal ?principal ;
             session:establishedBy ?x .
    ?x authn:achievedAssuranceLevel ?aal .
    ?aal authn:assuranceRank ?rank .
    FILTER (?rank < 2)
}

# CQ-2: For every route, which upstream does it reach and which policy
# enforcement point mediates it?
PREFIX core:    <https://w3id.org/examplebank/platform/core#>
PREFIX ingress: <https://w3id.org/examplebank/platform/ingress#>

SELECT ?route ?upstream ?pep WHERE {
    ?route a ingress:Route ;
           ingress:routesTo ?upstream .
    OPTIONAL { ?route core:enforcedBy ?pep }
}

# CQ-3: Who executed and who approved each policy change, and was any
# approver human?
PREFIX core: <https://w3id.org/examplebank/platform/core#>
PREFIX cp:   <https://w3id.org/examplebank/platform/control-plane#>

SELECT ?change ?executor ?approver ?humanApproved WHERE {
    ?change a cp:PolicyChangeEvent ;
            cp:executedBy ?executor ;
            cp:hasApproval ?a .
    ?a cp:approvedBy ?approver .
    BIND (EXISTS { ?approver a core:HumanPrincipal } AS ?humanApproved)
}

# CQ-4: Which attribute assertions back decisions about a principal, and
# which authoritative source issued each?
PREFIX authz: <https://w3id.org/examplebank/platform/authz#>

SELECT ?principal ?attrName ?attrValue ?issuer WHERE {
    ?assertion a authz:AttributeAssertion ;
               authz:aboutPrincipal ?principal ;
               authz:attributeName ?attrName ;
               authz:attributeValue ?attrValue ;
               authz:assertedBy ?issuer .
}

# CQ-5: For each Permit decision, trace the full assurance chain:
# decision -> session -> journey execution -> comprised events' methods
# and the execution's achieved AAL. This is the audit answer to "why did
# the platform believe this access was authorized?"
PREFIX core:    <https://w3id.org/examplebank/platform/core#>
PREFIX authn:   <https://w3id.org/examplebank/platform/authn#>
PREFIX session: <https://w3id.org/examplebank/platform/session#>
PREFIX authz:   <https://w3id.org/examplebank/platform/authz#>

SELECT ?decision ?principal ?policy ?method ?aal WHERE {
    ?decision a authz:PolicyDecision ;
              authz:decisionOutcome authz:outcome-permit ;
              authz:requestingPrincipal ?principal ;
              authz:evaluatedPolicy ?policy ;
              authz:withinSession ?s .
    ?s session:establishedBy ?x .
    ?x authn:comprisesEvent ?e ;
       authn:achievedAssuranceLevel ?aal .
    ?e authn:usedMethod ?method .
}

# CQ-6: Which workload principals exist, what are their SPIFFE identities,
# and which changes have they executed?
PREFIX core: <https://w3id.org/examplebank/platform/core#>
PREFIX cp:   <https://w3id.org/examplebank/platform/control-plane#>

SELECT ?workload ?spiffeId ?change WHERE {
    ?workload a core:WorkloadPrincipal ;
              core:identifier ?spiffeId .
    OPTIONAL { ?change cp:executedBy ?workload }
}
